def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, (And, Or)):
            if isinstance(arg.ops[0], arg.ops[1].__class__):
                new_args.append(arg.ops[0])
            elif isinstance(arg.ops[1], arg.ops[0].__class__):
                new_args.append(arg.ops[1])
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

