def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    major, minor, patch = map(int, version.split('.'))
    if patch < 999:
        return f'{major}.{minor}.{patch+1}'
    elif minor < 999:
        return f'{major}.{minor+1}.0'
    else:
        return f'{major+1}.0.0'

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = self.get('inventories/root/inventory.yaml')
    if not root_inventory:
        raise InventoryError("Missing inventory")

    version_inventories = {}
    content_digests = {}
    for version_dir in version_dirs:
        version_inventory = self.get("inventories/" + version_dir + "/inventory.yaml")
        if version_inventory:
            version_inventories[version_dir] = version_inventory
            for file in version_inventory["files"]:
                if file["status"] == "deleted":
                    continue
                filename = file["path"]
                digest = file["digest"]

                if filename not in root_inventory["files"]:
                    raise InventoryError("File " + filename + " in version " + version_dir + " is not in the root inventory")
                if digest != root_inventory["files"][filename]["digest"]:
                    content_digests[filename] = (version_dir, digest)
        else:
            raise InventoryError("Missing inventory for version " + version_dir)

    return version_inventories, content_digests

