def deep_merge_nodes(nodes):
    new_nodes = []
    for (key, value) in nodes:
        if value.load_type != yaml.MappingNode:
            continue
        existing_value = None
        for (sub_key, sub_value) in value.value:
            if sub_key.load_type != yaml.ScalarNode:
                continue
            if sub_value.load_type != yaml.ScalarNode:
                continue
            if existing_value:
                if sub_key.value in existing_value.value:
                    existing_value.value[sub_key.value] = sub_value
                else:
                    existing_value.value.append((sub_key, sub_value))
            else:
                existing_value = sub_value
        if existing_value:
            new_nodes.append((key, existing_value))
        else:
            new_nodes.append((key, value))

    return new_nodes

